const assert=require('assert/strict');
const poison='dark-deep-lv1-poison';
const skills={
 'dark-deep-lv1-spider-stab':[1,2,4], 'dark-deep-lv1-stalker-fang':[2,2,4],
 'dark-deep-lv1-guard-smash':[3,2,4], 'dark-deep-lv1-weaver-thread':[4,4,6],
 'dark-deep-lv1-matriarch-fang':[5,2,4], 'dark-deep-lv1-matriarch-mist':[5,4,6]
};
module.exports=function audit(s,route){
 const mins=Array(5).fill(100),damage=Array(5).fill(0),ticks=Array(5).fill(0),starts={},casts={},states=new Map();
 let applications=0,refreshes=0,cleanses=0,expiries=0;
 assert.equal(s.SoftEnrageCasts,0);assert.equal(s.HardEnrageCasts,0);
 assert.equal(s.InitialMonsters.length,5);
 assert.deepEqual(s.InitialMonsters.map(m=>[m.Wave,m.Position]),[[1,1],[2,1],[3,1],[4,1],[5,1]]);
 assert(s.InitialMonsters.every(m=>m.Defense===0));
 assert(s.MonsterPhaseRounds.every(p=>!p.IsActive&&p.Activations===0&&p.Breaks===0&&p.LinkedHits===0));
 for(const [ti,t]of s.RoundTrace.entries()){
  const r=t.Data.RoundNumber-1,used=new Set();
  assert.equal(t.Data.TotalWaveCount,5);
  assert(t.Data.OperationPotions.every(p=>!p.ItemCode));assert.equal(t.Data.ConsumableBuffs.length,0);
  assert(t.Data.HealingPotions.every(p=>p.UsesUsed<=2));
  for(const c of t.Data.Characters)assert.equal(c.MaxHp,s.Builds[+c.Actor.split(':')[1]-1].Stats.MaxHp,'LV1 has no maximum-life erosion');
  for(const e of t.Data.Events){
   if(starts[e.Monster]===undefined)starts[e.Monster]=r;
   if(e.Target?.startsWith('character:')&&e.HpAfter!==null&&e.TargetMaxHp>0){
    const slot=+e.Target.split(':')[1]-1;mins[slot]=Math.min(mins[slot],100*e.HpAfter/e.TargetMaxHp);
   }
   assert(!e.SkillCode?.startsWith('depth-placeholder-')&&!e.SkillCode?.startsWith('endgame-')&&!e.SkillCode?.startsWith('widow-'));
   assert.notEqual(e.ActionKind,2,'No soul imprint');
   if(e.Kind===0&&e.ActionKind===0&&e.Source?.startsWith('monster:')){
    const spec=skills[e.SkillCode];assert(spec,'Dedicated Dark LV1 skill only');
    assert.equal(e.Source,`monster:${spec[0]}:1`);assert(r-starts[e.Source]+1>=spec[1]);
    const castKey=e.Source+':'+e.SkillCode;
    if(!used.has(castKey)){
     const previous=s.RoundTrace[ti-1]?.Data.MonsterCooldowns.find(c=>c.Actor===e.Source&&c.SkillCode===e.SkillCode);
     if(previous)assert(r>=previous.ReadyAtRound,'Committed cast respects saved cooldown');
     assert.equal(t.Data.MonsterCooldowns.find(c=>c.Actor===e.Source&&c.SkillCode===e.SkillCode)?.ReadyAtRound,r+spec[2]);
     used.add(castKey);casts[e.SkillCode]=(casts[e.SkillCode]??0)+1;
    }
   }
   if(e.Status?.Code===poison){
    const st=e.Status;
    assert.equal(st.EffectType,'DamageOverTime');assert.equal(st.Stacks,1);assert(st.CanDispel&&!st.IsPositive);
    if([0,1].includes(e.StatusChange)){
     assert.equal(st.ExpiresAfterRound,r+2);assert(st.PerTickValue>=0);assert(st.AppliedRound<=r);
     if(e.StatusChange===0){assert.equal(st.AppliedRound,r);applications++;}
     else{const old=states.get(e.Target);assert(old,'Refresh existing poison');assert(st.PerTickValue>=old.PerTickValue);assert.equal(st.AppliedRound,old.AppliedRound);refreshes++;}
     states.set(e.Target,st);
    }else if([3,4].includes(e.StatusChange)){
     if(e.Kind===3){assert.equal(e.SkillCode,'acolyte-purify');cleanses++;}
     if(e.StatusChange===4){assert.equal(r,st.ExpiresAfterRound);expiries++;}
     states.delete(e.Target);
    }
   }
   if(e.Kind===0&&e.ActionKind===5&&e.Source?.startsWith('monster:')){
    const st=states.get(e.Target);assert(st,'Poison damage has a live snapshot');
    assert(r>st.AppliedRound&&r<=st.ExpiresAfterRound,'Only following poison rounds');
    assert.equal(e.Source,st.Source);assert.equal(e.SkillCode,st.SourceSkillCode);
    assert.equal(e.CalculatedAmount,st.PerTickValue);assert.equal(e.ActualAmount,Math.min(e.HpBefore,st.PerTickValue));
    assert(!e.IsCritical&&e.Element===null);assert.equal(e.ElementModifier,0);
    const slot=+e.Target.split(':')[1]-1;damage[slot]+=e.ActualAmount;ticks[slot]++;
   }
  }
  const live=t.Data.Statuses.filter(st=>st.EffectCode===poison);
  assert.equal(new Set(live.map(st=>st.Target)).size,live.length,'No duplicate poison stacks');
  for(const st of live){const old=states.get(st.Target);assert(old);for(const k of ['AppliedRound','ExpiresAfterRound','PerTickValue','Source','SourceSkillCode'])assert.equal(st[k],old[k]);}
  for(const key of states.keys())if(!live.some(st=>st.Target===key))states.delete(key);
 }
 if(route==='no-cleanse')assert.equal(cleanses,0);
 return {MinimumHpPercentBySlot:mins,PoisonApplications:applications,PoisonRefreshes:refreshes,PoisonCleanses:cleanses,PoisonNaturalExpiries:expiries,
  PoisonTicksBySlot:ticks,PoisonDamageBySlot:damage,CommittedMonsterSkillCasts:casts,
  ConstantMaximumLife:true,NoAdvancedMechanicOrLegacyEnrage:true,SingleStackRefreshAndSnapshotTicksVerified:true,LocalInitialAndSavedCooldownsVerified:true};
};
if(require.main===module){const fs=require('fs');for(const n of ['main','mixed','no-cleanse']){const a=JSON.parse(fs.readFileSync(__dirname+'/final-'+n+'.json')).Samples.map(s=>module.exports(s,n));console.log(JSON.stringify({Scenario:n,Runs:a.length,MeanPoisonDamage:a.reduce((x,v)=>x+v.PoisonDamageBySlot.reduce((y,z)=>y+z,0),0)/a.length,MeanCleanses:a.reduce((x,v)=>x+v.PoisonCleanses,0)/a.length,MeanTicks:a.reduce((x,v)=>x+v.PoisonTicksBySlot.reduce((y,z)=>y+z,0),0)/a.length}));}}
